import pandas as pd
import numpy as np
from scipy import stats

# Load all available experiments
dfs = {}
for eid in [1, 3, 6, 7, 8, 9]:
    try:
        df = pd.read_csv(f"experiment_{eid}_csv")
        dfs[f"exp{eid}"] = df
        print(f"\n=== Experiment {eid} ===")
        print(f"Columns: {list(df.columns)}")
        print(f"Shape: {df.shape}")
        print(df.describe().round(3))
        if df.select_dtypes('number').shape[1] >= 2:
            print("Correlations:")
            print(df.corr(numeric_only=True).round(3))
    except Exception as e:
        print(f"\nExperiment {eid}: Error - {e}")

# Check what yield-related columns exist across all data
print("\n=== YIELD COLUMNS ===")
for name, df in dfs.items():
    yield_cols = [c for c in df.columns if 'yield' in c.lower() or 'Yield' in c]
    if yield_cols:
        print(f"{name}: {yield_cols}")
        for col in yield_cols:
            print(f"  {col}: mean={df[col].mean():.3f}, sd={df[col].std():.3f}")
